const markWakeupReceiptsDeferred = `-- name: MarkWakeupReceiptsDeferred :many
UPDATE issue_wakeup_receipt SET deferred_at=now() WHERE id=ANY($1::uuid[]) AND processed_at IS NULL AND deferred_at IS NULL RETURNING id, wakeup_id, revision, event_key, event_type, payload, task_id, processed_at, created_at, coalesce_key, deferred_at, taint_ids
`

// Active-run defer: stamps the facts a running target held back and returns
// only those not stamped before, so the reason is recorded once per fact.
func (q *Queries) MarkWakeupReceiptsDeferred(ctx context.Context, ids []pgtype.UUID) ([]IssueWakeupReceipt, error) {
	rows, err := q.db.Query(ctx, markWakeupReceiptsDeferred, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []IssueWakeupReceipt{}
	for rows.Next() {
		var i IssueWakeupReceipt
		if err := rows.Scan(
			&i.ID,
			&i.WakeupID,
			&i.Revision,
			&i.EventKey,
			&i.EventType,
			&i.Payload,
			&i.TaskID,
			&i.ProcessedAt,
			&i.CreatedAt,
			&i.CoalesceKey,
			&i.DeferredAt,
			&i.TaintIds,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

